const rows = $input.all().map(i => i.json);
if (rows.length === 0) throw new Error('В сессии нет ответов');

const head = rows[0];

// ---- уровень 7.1: дословная транскрипция ----
const lines = [];
for (const r of rows) {
  lines.push('--- Вопрос ' + r.order_no + '  [' + r.competency_name + '] ---');
  lines.push('Аватар: ' + r.question_text);
  lines.push('Кандидат: ' + r.transcript);
  lines.push('');
}

// ---- материал для модели + агрегаты ----
const parts = [];
let kuSum = 0;
let kuCnt = 0;
let wpmSum = 0;
let wpmCnt = 0;
let pauseSum = 0;
const perComp = {};

for (const r of rows) {
  let ku = r.ku_level;
  if (ku === null) ku = 0;
  if (ku === undefined) ku = 0;
  ku = Number(ku);

  if (ku > 0) {
    kuSum = kuSum + ku;
    kuCnt = kuCnt + 1;
    if (!perComp[r.competency_name]) perComp[r.competency_name] = [];
    perComp[r.competency_name].push(ku);
  }

  const w = Number(r.wpm);
  if (w > 0) { wpmSum = wpmSum + w; wpmCnt = wpmCnt + 1; }

  const p = Number(r.pause_total_sec);
  if (p > 0) pauseSum = pauseSum + p;

  let b = 'Компетенция: ' + r.competency_name + '\n';
  b += 'Вопрос: ' + r.question_text + '\n';
  b += 'Ответ кандидата: ' + r.transcript + '\n';
  b += 'Оценка КУ: ' + ku + '. ' + r.rationale + '\n';
  parts.push(b);
}

let avgKu = 0;
if (kuCnt > 0) avgKu = Math.round((kuSum / kuCnt) * 10) / 10;

let avgWpm = 0;
if (wpmCnt > 0) avgWpm = Math.round(wpmSum / wpmCnt);

// средний КУ по каждой компетенции
const compTable = [];
for (const name of Object.keys(perComp)) {
  const arr = perComp[name];
  let s = 0;
  for (const v of arr) s = s + v;
  compTable.push({ competency: name, ku: Math.round((s / arr.length) * 10) / 10 });
}

return [{ json: {
  session_id:    head.session_id,
  employee_id:   head.employee_id,
  or_id:         head.or_id,
  employee_name: head.employee_name,
  is_training:   head.is_training,
  flag_count:    Number(head.flag_count),
  answers_count: rows.length,
  avg_ku:        avgKu,
  avg_wpm:       avgWpm,
  pause_total:   Math.round(pauseSum),
  comp_table:    compTable,
  transcript:    lines.join('\n'),
  material:      parts.join('\n---\n')
}}];

const meta = $('2. Транскрипция и материал').first().json;

let parsed = null;

function eat(v, depth) {
  if (parsed !== null) return;
  if (v === null) return;
  if (v === undefined) return;
  if (depth > 5) return;

  if (Array.isArray(v)) { for (const x of v) eat(x, depth + 1); return; }

  if (typeof v === 'string') {
    const c = v.indexOf('{');
    const d = v.lastIndexOf('}');
    if (c === -1) return;
    if (d <= c) return;
    const frag = v.slice(c, d + 1);
    try { eat(JSON.parse(frag), depth + 1); }
    catch (e1) {
      try { eat(JSON.parse(frag.replace(/,\s*([}\]])/g, '$1')), depth + 1); }
      catch (e2) { return; }
    }
    return;
  }

  if (typeof v === 'object') {
    if (v.employee_summary !== undefined) { parsed = v; return; }
    if (v.strengths !== undefined) { parsed = v; return; }
    for (const x of Object.values(v)) eat(x, depth + 1);
  }
}

for (const item of $input.all()) eat(item.json, 0);

function arr(v) {
  if (Array.isArray(v)) return v.map(x => String(x));
  if (typeof v === 'string') { if (v.length > 0) return [v]; }
  return [];
}

let strengths = [];
let gaps = [];
let recs = [];
let summary = 'Отчёт сформирован. Обратная связь будет дополнена ответственным за развитие.';

if (parsed !== null) {
  strengths = arr(parsed.strengths);
  gaps = arr(parsed.gaps);
  recs = arr(parsed.recommendations);
  if (parsed.employee_summary) summary = String(parsed.employee_summary);
}

// ---- уровень 7.2: полный отчёт для ОР ----
const reportOr = {
  employee_name:  meta.employee_name,
  session_id:     meta.session_id,
  is_training:    meta.is_training,
  answers_count:  meta.answers_count,
  avg_ku:         meta.avg_ku,
  competencies:   meta.comp_table,
  behavior: {
    avg_wpm:         meta.avg_wpm,
    pause_total_sec: meta.pause_total
  },
  red_flags_count: meta.flag_count,
  strengths:       strengths,
  gaps:            gaps,
  recommendations: recs,
  model:           'llama3.2:3b'
};

// ---- уровень 7.3: фильтр для сотрудника ----
// Сюда НЕ попадают: красные флаги, средний КУ, оценки по компетенциям,
// обоснования модели, поведенческие метрики.
const reportEmp = {
  employee_name:   meta.employee_name,
  session_id:      meta.session_id,
  is_training:     meta.is_training,
  summary:         summary,
  strengths:       strengths,
  next_steps:      recs,
  note:            'Обратная связь проверена ответственным за развитие.'
};

return [{ json: {
  session_id:  meta.session_id,
  parsed_ok:   parsed !== null,
  report_or:   reportOr,
  report_emp:  reportEmp
}}];

